'use strict';
(()=>{
  const TABLE='property_rental_comparables',cache=new Map(),pending=new Map();
  const uid=()=>typeof cloudUser!=='undefined'?cloudUser?.id:null;
  const pid=()=>typeof selectedPropertyId!=='undefined'?selectedPropertyId:null;
  const clone=v=>JSON.parse(JSON.stringify(v));
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let account=null,editing=null,saving=false,request=0,lastReport='',timer;
  function reset(){if(account===uid())return;account=uid();cache.clear();pending.clear();lastReport='';editing=null;request++;document.getElementById('ptRentalsDialog')?.close();window.MarketRentSupport?.unmount?.();}
  function guard(user){if(!user||user!==uid())throw Error('Your sign-in changed. Reopen Rental Comps.');}
  const useful=e=>!!(e&&(e.comparables?.length||Number(e.concludedRent)>0||Number(e.estimate)>0));
  async function load(id,force=false){reset();const user=uid();guard(user);if(!id)throw Error('Save the subject property first.');if(!force&&cache.has(id))return cache.get(id);if(pending.has(id))return pending.get(id);
    const task=(async()=>{const {data,error}=await cloudClient.from(TABLE).select('property_id,revision,evidence').eq('property_id',id).maybeSingle();guard(user);if(error)throw Error('Rental comps could not be loaded. '+error.message);let row=data;
      if(!row){const result=await cloudClient.from('analyses').select('id,name,assumptions,updated_at').eq('property_id',id).order('updated_at',{ascending:false});guard(user);if(result.error)throw result.error;const legacy=(result.data||[]).find(a=>useful(a.assumptions?.marketRentSupport));const evidence=clone(legacy?.assumptions?.marketRentSupport||{});row={property_id:id,revision:0,evidence:{...evidence,version:1,comparables:evidence.comparables||[]},legacy:legacy?.name||null};}
      cache.set(id,row);return row;})();pending.set(id,task);try{return await task;}finally{if(pending.get(id)===task)pending.delete(id);}
  }
  function reportSupport(){reset();return cache.get(pid())?.evidence||null;}
  async function prepareReport(){const id=pid(),user=uid();if(!id)return;await load(id,true);guard(user);if(id!==pid())throw Error('The open property changed. Generate the report again.');window.ReportMarketRentSupport?.apply();window.PropertyThesisReportReader?.apply?.();}
  function status(text){const el=document.querySelector('#ptRentalsDialog [data-prc-status]');if(el)el.textContent=text;}
  async function open(id){reset();if(!uid())throw Error('Sign in to manage rental comps.');if(saving)return;if(editing&&!close())return;const ticket=++request,user=uid();let d=document.getElementById('ptRentalsDialog');if(!d){d=document.createElement('dialog');d.id='ptRentalsDialog';d.setAttribute('aria-labelledby','ptRentalsTitle');d.innerHTML='<h2 id="ptRentalsTitle">Rental Comps</h2><button type="button" class="btn ghost" data-prc-close>Close</button><p data-prc-subject></p><p data-prc-help></p><div data-prc-host></div><div class="prc-actions"><button type="button" class="btn primary" data-prc-save>Save Rental Comps</button><p role="status" data-prc-status></p></div>';document.body.appendChild(d);d.querySelector('[data-prc-close]').onclick=close;d.querySelector('[data-prc-save]').onclick=()=>save().catch(e=>status(e.message));d.addEventListener('cancel',e=>{e.preventDefault();close();});}
    d.querySelector('[data-prc-host]').textContent='Loading saved rental comps…';d.querySelector('[data-prc-save]').disabled=true;if(!d.open)d.showModal();
    try{const row=await load(id,true);const p=await cloudClient.from('properties').select('id,address,name').eq('id',id).single();guard(user);if(ticket!==request||!d.open)return;if(p.error||!p.data)throw Error('This saved property is unavailable.');const a=await cloudClient.from('analyses').select('assumptions').eq('property_id',id).order('updated_at',{ascending:false}).limit(1);guard(user);if(ticket!==request||!d.open)return;if(a.error)throw a.error;const assumptions=a.data?.[0]?.assumptions||{},draft=clone(row.evidence);if(typeof window.MarketRentSupport?.mount!=='function')throw Error('The rental editor could not load. Close this window and refresh the page to retry.');editing={id,user,row,draft,initial:JSON.stringify(draft)};
      d.querySelector('[data-prc-subject]').textContent=p.data.address||p.data.name;d.querySelector('[data-prc-help]').textContent=(row.legacy?'Existing selections from “'+row.legacy+'” are shown. Save to use them across this property’s reports. ':'')+'Research rental listings and select the evidence for this property. Click Save Rental Comps to include your selections in its reports. Closing without saving leaves the saved research unchanged.';
      d.querySelector('[data-prc-host]').textContent='';window.MarketRentSupport.mount({host:d.querySelector('[data-prc-host]'),dialog:d,store:draft,address:p.data.address||assumptions.address||p.data.name,close});editing.initial=JSON.stringify(window.MarketRentSupport.getDraft());d.querySelector('[data-prc-save]').disabled=false;status(row.revision?'Saved selections loaded.':'No property-level selection saved yet.');
    }catch(e){if(ticket===request){editing=null;status(e.message);}}
  }
  async function save(){if(!editing||saving)return;const ctx=editing;guard(ctx.user);const evidence={...clone(window.MarketRentSupport.getDraft()),version:1};if((evidence.comparables||[]).length>15)throw Error('Select at most 15 rental listings.');saving=true;const button=document.querySelector('[data-prc-save]');button.disabled=true;status('Saving rental comps…');
    try{const q=ctx.row.revision?cloudClient.from(TABLE).update({revision:ctx.row.revision+1,evidence}).eq('property_id',ctx.id).eq('revision',ctx.row.revision):cloudClient.from(TABLE).insert({property_id:ctx.id,user_id:ctx.user,revision:1,evidence});const {data,error}=await q.select('property_id,revision,evidence').maybeSingle();guard(ctx.user);if(error||!data){cache.delete(ctx.id);throw Error('Save was not confirmed. Another session may have changed these comps. Close and reopen before retrying.');}cache.set(ctx.id,data);ctx.row=data;ctx.initial=JSON.stringify(window.MarketRentSupport.getDraft());if(pid()===ctx.id){window.ReportMarketRentSupport?.apply();window.PropertyThesisReportReader?.apply?.();}status((evidence.comparables||[]).filter(c=>c.included!==false).length+' rental comps saved under this property. Reports will use this research.');}
    finally{saving=false;if(button)button.disabled=false;}
  }
  function close(){if(saving)return false;if(editing&&typeof window.MarketRentSupport?.getDraft==='function'&&JSON.stringify(window.MarketRentSupport.getDraft())!==editing.initial&&!confirm('Close without saving your rental comps selections?'))return false;request++;editing=null;window.MarketRentSupport?.unmount?.();document.getElementById('ptRentalsDialog')?.close();return true;}
  function decorate(){reset();for(const card of document.querySelectorAll('#propertyhub .hub-card')){const opener=card.querySelector('[data-stage7-file],[data-hub-open]'),id=opener?.dataset.stage7File||opener?.dataset.hubOpen,actions=card.querySelector('.pt-hub-primary-flow')||card.querySelector('.hub-actions');if(id&&actions&&!actions.querySelector('[data-prc-open]')){const b=document.createElement('button');b.type='button';b.className='btn secondary';b.dataset.prcOpen=id;b.textContent='Rental Comps';actions.appendChild(b);}}
    const grid=document.querySelector('#dashboard .grid');let panel=document.getElementById('ptPropertyRentalsPanel');if(grid&&!panel){panel=document.createElement('section');panel.id='ptPropertyRentalsPanel';panel.className='card span-12';grid.appendChild(panel);}if(panel){const html='<h2>Rental Comps</h2><p>Add optional rental-market evidence to this property’s reports.</p>'+(pid()?'<button type="button" class="btn secondary" data-prc-open="'+esc(pid())+'">Manage Rental Comps</button>':'<p>Save the property first to add rental comps.</p>');if(panel.innerHTML!==html)panel.innerHTML=html;}
    const key=uid()+':'+pid();if(uid()&&pid()&&lastReport!==key){lastReport=key;const id=pid();window.ReportMarketRentSupport?.apply();load(id).then(()=>{if(pid()===id)window.ReportMarketRentSupport?.apply();}).catch(()=>{lastReport='';});}
  }
  const schedule=()=>{clearTimeout(timer);timer=setTimeout(decorate,120);};
  document.addEventListener('click',e=>{const b=e.target.closest?.('[data-prc-open]');if(b){e.preventDefault();open(b.dataset.prcOpen).catch(e=>alert(e.message));}schedule();});
  document.addEventListener('propertythesis:analysis-loaded',()=>{lastReport='';schedule();});
  const style=document.createElement('style');style.textContent='#ptRentalsDialog{width:min(1160px,94vw);max-height:90vh;overflow:auto;border:1px solid #cad8e2;border-radius:14px;padding:24px;color:#18364a}#ptRentalsDialog::backdrop{background:#1239}#ptRentalsDialog .prc-actions{position:sticky;bottom:-24px;padding:16px;background:white;border-top:1px solid #ccd}#ptRentalsDialog .ptr-note,#ptRentalsDialog .ptr-comp-meta,#ptRentalsDialog .ptr-comp-toggle{font-size:13px}#ptRentalsDialog .ptr-comp h4{font-size:15px}#ptRentalsDialog .ptr-stat span{font-size:11px}#ptRentalsDialog input,#ptRentalsDialog select,#ptRentalsDialog textarea{font-size:14px;max-width:100%;box-sizing:border-box}#ptRentalsDialog .field{min-width:0}#ptRentalsDialog .ptr-manual{margin:18px 0;padding:15px;background:#f4f8fb;border:1px solid #b9cee0;border-radius:10px}#ptRentalsDialog .pt-se-note,#ptRentalsDialog .pt-se-status{font-size:13px}#ptRentalsDialog .pt-se-field label{font-size:12px}#ptRentalsDialog .pt-se-field input,#ptRentalsDialog .pt-se-field select{font-size:14px;min-height:40px}#ptRentalsDialog .pt-se-table{font-size:13px}#ptRentalsDialog .pt-se-head p{font-size:13px}';document.head.appendChild(style);
  window.PropertyThesisPropertyRentals={open,close,save,load,reportSupport,prepareReport};new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});schedule();
})();
